def diagonal_traverse(matrix: List[List[int]]) -> List[int]:
    """ From a given matrix (list of lists), traverse the elements diagonally starting from the top-left corner and
    return a list of the traversed elements.
    >>> diagonal_traverse([[1, 2, 3], [4, 5, 6], [7, 8, 9]])
    [1, 2, 4, 3, 5, 7, 6, 8, 9]
    """
    if not matrix or not matrix[0]:
        return []
    result = []
    rows, cols = len(matrix), len(matrix[0])
    for i in range(rows):
        j = 0
        while i >= 0 and j < cols:
            result.append(matrix[i][j])
            i, j = i - 1, j + 1
    for j in range(1, cols):
        i = rows - 1
        while i >= 0 and j < cols:
            result.append(matrix[i][j])
            i, j = i - 1, j + 1
    return result


def min_path_sum(grid: List[List[int]]) -> int:
    """ From a given grid (list of lists), find the minimum path sum from top-left to bottom-right corner by
    only moving either down or right at each step.
    >>> min_path_sum([[1, 3, 1], [1, 5, 1], [4, 2, 1]])
    7
    """
    if not grid or not grid[0]:
        return 0
    rows, cols = len(grid), len(grid[0])
    dp = [[0 for _ in range(cols)] for _ in range(rows)]
    dp[0][0] = grid[0][0]
    for i in range(1, rows):
        dp[i][0] = dp[i - 1][0] + grid[i][0]
    for j in range(1, cols):
        dp[0][j] = dp[0][j - 1] + grid[0][j]
    for i in range(1, rows):
        for j in range(1, cols):
            dp[i][j] = min(dp[i - 1][j], dp[i][j - 1]) + grid[i][j]
    return dp[-1][-1]


