def rescale_to_unit_in_place(numbers: List[float]) -> None:
    """ Apply in-place a linear transform to that list, such that the smallest number will become 0
    and the largest will become 1
    """
    if len(numbers) < 2:
        raise ValueError("Cannot rescale a list with less than 2 elements")
    min_number = min(numbers)
    max_number = max(numbers)
    scale = 1 / (max_number - min_number) if max_number != min_number else 0
    for i, x in enumerate(numbers):
        numbers[i] = (x - min_number) * scale


