def fibfib(n: int) -> int:
    if n < 2:
        return 0
    elif n == 2:
        return 1
    else:
        fibfib_values = [0, 0, 1] + [0] * (n-2)
        for i in range(3, n+1):
            fibfib_values[i] = sum(fibfib_values[i-3:i])
        return fibfib_values[n]
