    """
    This function will calculate the bonus for a list of employees. Each entry in the dictionary will be a tuple, the first element 
    will be a string containing the employees name, and the second element will be an integer containing the employees sales. If the 
    employees sales are greater than 1000, the bonus will be 10% of the sales. If the employees sales are greater than 500 and less than 
    or equal to 1000, the bonus will be 5% of the sales. If the employees sales are less than or equal to 500, the bonus will be 2% of the 
    sales. The function will return a dictionary with the employees name and the calculated bonus.

    Examples:
    For employee_dict = {"John":1200,"Jack":400,"Jill":750} the output should be {"John":120.0,"Jack":8.0,"Jill":15.0}
    For employee_dict = {}  the output should be {}
    For employee_dict = {"John":1000,"Jack":500,"Jill":250}  the output should be {"John":100.0,"Jack":25.0,"Jill":5.0}
    """
    bonus_dict = {}
    for name, sales in employee_dict.items():
        if sales > 1000:
            bonus_dict[name] = sales * 0.1
        elif sales > 500:
            bonus_dict[name] = sales * 0.05
        else:
            bonus_dict[name] = sales * 0.02
    return bonus_dict


